input.new_str:
/** Limits a value to the range [min, max]. */
export function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { clamp } from '../src/clamp.ts';

test('returns the value when within range', () => {
  assert.equal(clamp(5, 0, 10), 5);
});

test('raises values below the minimum', () => {
  assert.equal(clamp(-3, 0, 10), 0);
});

test('lowers values above the maximum', () => {
  assert.equal(clamp(42, 0, 10), 10);
});

test('keeps boundary values unchanged', () => {
  assert.equal(clamp(0, 0, 10), 0);
  assert.equal(clamp(10, 0, 10), 10);
});

